// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { PriceChange } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/PriceChange)

figma.connect(PriceChange, FIGMA_NODE_URL, {
  props: {
    hideIcon: figma.boolean('hideIcon'),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
  },
  example: ({ hideIcon, size }) => (
    <PriceChange hideIcon={hideIcon} size={size}></PriceChange>
  ),
});
